def _load_supplement():
    import json
    from pathlib import Path
    path = Path(__file__).with_name("supplement_data.json")
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}


def get_page_dict(lang):
    if not lang or lang == "ko":
        return {}
    base = dict(PAGE_TRANSLATIONS.get("en", {}))
    base.update(PAGE_TRANSLATIONS.get(lang, {}))
    sup = _load_supplement()
    if sup:
        base.update(sup.get("en", {}))
        base.update(sup.get(lang, {}))
    return base
